#!/usr/bin/env bash
# Observability tests + audit (privacy_audit.py reads the kept capture in $SPEAKEASY_HOME, read-only, when there is one). Usage: ./run_audit.sh   (audit a Mac log copy: python3 audit_logs.py /path/runs.jsonl --screen 3024x1964 --md out.md)
cd "$(dirname "$0")" && python3 test_observe.py; python3 tts/test_tts.py; python3 nosel/test_nosel.py; python3 gate/test_gate.py; python3 stream/test_stream.py; python3 superlative/test_superlative.py; python3 focus/test_focus.py; python3 verbatim/test_verbatim.py; python3 doc/test_doc.py; python3 perf/test_perf_audit.py; BOXACC_QUICK=${BOXACC_QUICK:-1} python3 boxacc/test_box_accuracy.py; SE_HOME="${SPEAKEASY_HOME:-$HOME/.speakeasy}"; [ -f "$SE_HOME/last_capture.png" ] && SPEAKEASY_HOME="$SE_HOME" python3 privacy_audit.py; [ -d "${SPEAKEASY_LOGS:-$HOME/.speakeasy/logs}" ] && python3 perf/run_health.py "${SPEAKEASY_LOGS:-$HOME/.speakeasy/logs}" --last 3; [ -d "${SPEAKEASY_LOGS:-$HOME/.speakeasy/logs}" ] && python3 perf/audit_perf.py "${SPEAKEASY_LOGS:-$HOME/.speakeasy/logs}"
